	struct span_instruction
	{
		std::uint32_t va;
		std::string_view hex;
		op how;
		std::uint8_t condition; // branch: 0x0-0xf = jcc condition code
		std::uint32_t target;
	};
	struct cave
	{
		std::uint32_t va;      // the imm8 row that needs a wider number
		std::uint8_t first, count; // its instructions in span_instructions
		std::uint32_t resume;  // first byte after the span
	};
